@layer paper-shaders {
  :where([data-paper-shader]) {
  isolation: isolate; position: relative;
  & canvas { contain: strict; display: block; position: absolute; inset: 0px; z-index: -1; width: 100%; height: 100%; border-radius: inherit; corner-shape: inherit; }
}
}

:root { --bg: #000; --panel: #0c0c0e; --line: #1e1e22; --text: #f5f5f7; --muted: #a1a1a6; --faint: #6e6e73; --radius: 20px; }html { scroll-behavior: smooth; background: var(--bg); }html, body, #root { margin: 0px; min-height: 100%; background: var(--bg); }body { font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", system-ui, sans-serif; font-feature-settings: "ss01"; color: var(--text); -webkit-font-smoothing: antialiased; }button { font: inherit; color: inherit; }a { color: inherit; }.visually-hidden { width: 1px; height: 1px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); white-space: nowrap; position: absolute !important; }.wrap { width: min(1000px, 100% - 48px); margin-inline: auto; }.material { background: rgba(28, 28, 30, 0.58); backdrop-filter: saturate(180%) blur(24px); border: 1px solid rgba(255, 255, 255, 0.09); box-shadow: rgba(255, 255, 255, 0.06) 0px 1px inset; }.nav { position: sticky; top: 0px; z-index: 10; border-width: 0px 0px 1px; box-shadow: none; background: rgba(0, 0, 0, 0.62); }.nav-inner { display: flex; align-items: center; justify-content: space-between; padding: 14px 0px; }.brand { display: inline-flex; align-items: center; gap: 10px; font-weight: 600; font-size: 16px; letter-spacing: -0.01em; text-decoration: none; }.brand-dot { width: 18px; height: 18px; border-radius: 6px; background: conic-gradient(from 200deg, rgb(123, 92, 255), rgb(255, 79, 154), rgb(255, 179, 71), rgb(60, 242, 160), rgb(123, 92, 255)); }.button { display: inline-flex; align-items: center; padding: 10px 18px; border-radius: 999px; font-size: 14px; font-weight: 600; text-decoration: none; border: 0px; cursor: pointer; }.button.ghost { border: 1px solid var(--line); background: var(--panel); }.button.ghost:hover { border-color: rgb(58, 58, 64); }.hero { padding: 64px 0px 0px; }.eyebrow { margin: 0px 0px 16px; font-size: 13px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); }h1 { margin: 0px; font-size: clamp(44px, 7vw, 76px); line-height: 1; letter-spacing: -0.045em; font-weight: 600; }.lede { max-width: 560px; margin: 20px 0px 0px; font-size: 19px; line-height: 1.5; color: var(--muted); }.stage { position: relative; margin: 48px 0px 0px; aspect-ratio: 16 / 9; border-radius: var(--radius); overflow: hidden; border: 1px solid var(--line); background: var(--panel); }.stage-caption { position: absolute; inset: auto 0px 0px; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 40px 20px 16px; background: linear-gradient(to top, rgba(0, 0, 0, 0.72), rgba(0, 0, 0, 0)); font-size: 14px; color: rgba(245, 245, 247, 0.86); }.stage-caption strong { color: var(--text); margin-right: 6px; }.stage-nav { display: inline-flex; align-items: center; gap: 10px; flex-shrink: 0; }.stage-nav button { width: 30px; height: 30px; border-radius: 999px; border: 1px solid rgba(255, 255, 255, 0.25); background: rgba(0, 0, 0, 0.35); cursor: pointer; line-height: 1; }.stage-count { font-variant-numeric: tabular-nums; color: var(--muted); }.waitlist { max-width: 480px; margin-top: 28px; }.waitlist-field { display: flex; align-items: center; gap: 6px; padding: 5px 5px 5px 18px; border-radius: 999px; }.waitlist-field:focus-within { border-color: rgba(255, 255, 255, 0.28); }.waitlist-field input[type="email"] { flex: 1 1 0%; min-width: 0px; padding: 8px 0px; border: 0px; background: transparent; color: var(--text); font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: 15px; outline: none; }.waitlist-field input[type="email"]::placeholder { color: var(--faint); }.waitlist-field button { flex-shrink: 0; padding: 10px 18px; border: 0px; border-radius: 999px; background: var(--text); color: rgb(0, 0, 0); font-size: 14px; font-weight: 600; cursor: pointer; }.waitlist-field button:disabled { opacity: 0.7; cursor: progress; }.waitlist-note { margin: 10px 0px 0px 18px; font-size: 13px; color: var(--faint); }.waitlist-note.error { color: rgb(255, 138, 128); }.waitlist-done { max-width: 480px; margin: 28px 0px 0px; padding: 14px 18px; border-radius: 16px; border: 1px solid var(--line); background: var(--panel); font-size: 15px; }.showcase { margin-top: 120px; }.showcase img, .feature-media img { display: block; width: 100%; height: auto; border-radius: var(--radius); border: 1px solid var(--line); }.card { position: relative; overflow: hidden; margin-top: 28px; border-radius: 28px; border: 1px solid rgba(255, 255, 255, 0.09); background: var(--panel); }.showcase + .card { margin-top: 120px; }.card-shader { position: absolute; inset: 0px; }.card-material { position: absolute; inset: 0px; background: rgba(6, 6, 8, 0.7); backdrop-filter: blur(56px) saturate(170%); }.card-content { position: relative; display: grid; gap: 32px; padding: 40px; }.card-content h2, .card-content p, .card-content img { margin-block-end: 0px; }.feature-copy { max-width: 600px; }.card-content > * { min-width: 0px; }.feature-media img { box-shadow: rgba(0, 0, 0, 0.45) 0px 24px 60px; }.tag { padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; letter-spacing: 0.01em; }.tag.beta { background: rgba(255, 159, 67, 0.16); color: rgb(255, 179, 107); }.tag.soon { background: rgba(123, 92, 255, 0.18); color: rgb(179, 164, 255); }.agent { padding: 26px; border-radius: 16px; font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 13px; line-height: 1.7; color: var(--muted); }.agent p { margin: 0px 0px 6px; }.agent-you, .agent-bot, .agent-tool { display: inline-block; min-width: 108px; margin-right: 8px; }.agent-you { color: rgb(138, 180, 255); }.agent-bot { color: rgb(60, 242, 160); }.agent-tool { color: rgb(255, 179, 107); }.agent-ok { color: rgb(60, 242, 160); }.market { width: 100%; box-sizing: border-box; display: flex; align-items: center; gap: 8px; padding: 12px; border-radius: 18px; }.market-track { min-width: 0px; display: flex; gap: 12px; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; flex: 1 1 0%; padding: 2px; }.market-track::-webkit-scrollbar { display: none; }.market-card { flex: 0 0 188px; padding: 0px; border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 12px; overflow: hidden; background: rgb(13, 13, 15); text-align: left; cursor: pointer; scroll-snap-align: center; }.market-card[aria-current="true"] { border-color: rgba(255, 255, 255, 0.8); }.market-thumb { position: relative; display: block; aspect-ratio: 16 / 10; background: rgb(17, 17, 17); }.market-name { display: block; padding: 8px 10px; font-size: 13px; font-weight: 600; }.market-nav { flex-shrink: 0; width: 32px; height: 32px; border-radius: 999px; border: 1px solid rgba(255, 255, 255, 0.18); background: rgba(255, 255, 255, 0.06); cursor: pointer; }.join { margin-top: 120px; padding: 56px; border-radius: 28px; border: 1px solid rgba(255, 255, 255, 0.09); background: radial-gradient(120% 140% at 0% 0%,rgba(123,92,255,.18),transparent 55%),var(--panel); }.join h2 { margin: 0px; font-size: clamp(32px, 4.4vw, 48px); letter-spacing: -0.035em; font-weight: 600; }.join p { max-width: 520px; margin: 14px 0px 0px; font-size: 17px; line-height: 1.5; color: var(--muted); }.footer { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px; margin-top: 72px; padding: 24px 0px 40px; border-top: 1px solid var(--line); font-size: 13px; color: var(--faint); }.footer a:hover { color: var(--text); }@media (max-width: 760px) {
  .hero { padding-top: 32px; }
  .card-content { padding: 24px; }
  .showcase { margin-top: 80px; }
  .join { padding: 32px 24px; margin-top: 100px; }
  .stage-caption > span:first-child { display: none; }
}.marketplace { position: relative; min-height: 100vh; margin-top: 140px; display: flex; overflow: hidden; }.marketplace-shader { position: absolute; inset: 0px; background: rgb(7, 7, 10); }.marketplace-scrim { position: absolute; inset: 0px; background: linear-gradient(rgba(0, 0, 0, 0.35), rgba(0, 0, 0, 0) 12%), linear-gradient(to top, rgba(0, 0, 0, 0.55), rgba(0, 0, 0, 0.12) 30%, rgba(0, 0, 0, 0) 50%); }.marketplace-inner { position: relative; display: flex; flex-direction: column; justify-content: flex-end; gap: 24px; padding: 120px 0px 40px; }.marketplace-copy h2 { margin: 14px 0px 0px; font-size: clamp(44px, 7vw, 84px); line-height: 0.98; letter-spacing: -0.045em; font-weight: 600; text-shadow: rgba(0, 0, 0, 0.35) 0px 2px 30px; }.marketplace-copy p { max-width: 520px; margin: 16px 0px 0px; font-size: 18px; line-height: 1.5; color: rgba(245, 245, 247, 0.86); }.marketplace-now { margin-top: 12px; }.marketplace-name { margin: 0px; font-size: 22px; font-weight: 600; letter-spacing: -0.02em; }.marketplace-desc { margin: 4px 0px 0px; color: rgba(245, 245, 247, 0.8); }.marketplace-colors { display: flex; flex-wrap: wrap; gap: 10px 16px; margin: 14px 0px 0px; padding: 0px; list-style: none; font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 12px; color: rgba(245, 245, 247, 0.8); }.marketplace-colors li { display: flex; align-items: center; gap: 7px; }.marketplace-colors span { width: 12px; height: 12px; border-radius: 999px; border: 1px solid rgba(255, 255, 255, 0.4); }.marketplace .join, .marketplace + .join { margin-top: 120px; }.shader-footer { position: relative; min-height: 520px; margin-top: 140px; display: flex; overflow: hidden; }.shader-footer-shader { position: absolute; inset: 0px; background: rgb(7, 7, 10); }.shader-footer-scrim { position: absolute; inset: 0px; background: linear-gradient(rgb(0, 0, 0), rgba(0, 0, 0, 0) 35%), linear-gradient(to top, rgba(0, 0, 0, 0.55), rgba(0, 0, 0, 0) 45%); }.shader-footer-inner { position: relative; display: flex; flex-direction: column; justify-content: flex-end; padding-bottom: 32px; }.shader-footer-mark { margin: 0px; font-size: clamp(64px, 14vw, 180px); font-weight: 700; line-height: 0.9; letter-spacing: -0.06em; color: rgba(255, 255, 255, 0.92); mix-blend-mode: overlay; }.shader-footer-links { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px; margin-top: 28px; padding-top: 18px; border-top: 1px solid rgba(255, 255, 255, 0.22); font-size: 13px; color: rgba(255, 255, 255, 0.82); }.shader-footer-links a:hover { color: rgb(255, 255, 255); }@media (max-width: 760px) {
  .card-content { padding: 24px; }
  .marketplace { min-height: 88vh; }
  .shader-footer { min-height: 380px; }
}.marketplace-copy .tag { display: inline-block; background: rgba(20, 16, 40, 0.6); color: rgb(207, 196, 255); }.hero-title { display: grid; }.hero-line { animation: 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) 0s 1 normal both running title-in; }.shader-word { position: relative; display: inline-block; width: fit-content; font-size: 1.9em; line-height: 0.95; letter-spacing: -0.06em; font-weight: 700; }.shader-word-canvas { position: absolute; inset: 4px 6px; overflow: hidden; filter: saturate(1.5) brightness(1.55) contrast(1.05); }.shader-word-mask { position: relative; display: block; padding: 0px 0.08em 0px 0px; background: rgb(0, 0, 0); color: rgb(255, 255, 255); mix-blend-mode: multiply; }.shader-letter { display: inline-block; animation: 1s cubic-bezier(0.2, 0.8, 0.2, 1) 0s 1 normal both running letter-in; }@keyframes title-in { 
  0% { opacity: 0; transform: translateY(18px); filter: blur(8px); }
  100% { opacity: 1; transform: none; filter: none; }
}@keyframes letter-in { 
  0% { opacity: 0; transform: translateY(0.35em) scale(0.92); filter: blur(10px); }
  100% { opacity: 1; transform: none; filter: none; }
}@media (prefers-reduced-motion: reduce) {
  .hero-line, .shader-letter { animation: auto ease 0s 1 normal none running none; }
}

.v7 { --accent: #0a84ff; --accent-down: #0070e0; --label: rgba(255, 255, 255, .88); --secondary: rgba(255, 255, 255, .55); --tertiary: rgba(255, 255, 255, .32); --separator: rgba(255, 255, 255, .09); --detail: #29292b; --inspector: #222224; --sidebar: #1d1d1f; --insp: 304px; --ease-out: cubic-bezier(.2, .8, .2, 1); --spring: cubic-bezier(.34, 1.4, .5, 1); position: fixed; inset: 0px; overflow: hidden; font-size: 13px; line-height: 1.3; color: var(--label); letter-spacing: -0.003em; cursor: default; user-select: none; -webkit-tap-highlight-color: transparent; }:where(.v7) button { border: 0px; background: none; padding: 0px; cursor: default; font: inherit; color: inherit; }.v7 input, .v7 textarea { user-select: text; }.v7 :focus-visible { outline: rgba(10, 132, 255, 0.55) solid 3px; outline-offset: 1px; }.v7 ~ .variation-nav { z-index: 9500; }.v7 .beta { display: inline-block; padding: 1px 6px; border-radius: 999px; font-size: 10px; font-weight: 600; letter-spacing: 0px; vertical-align: 0.15em; color: rgb(255, 159, 10); background: rgba(255, 159, 10, 0.2); }.wallpaper { position: fixed; inset: 0px; z-index: 0; background: rgb(11, 22, 48); }.tahoe { position: absolute; inset: 0px; background: radial-gradient(70% 55% at 78% 108%, rgba(83, 160, 255, 0.85), transparent 70%), radial-gradient(60% 50% at 10% 100%, rgba(40, 92, 196, 0.8), transparent 70%), radial-gradient(80% 60% at 30% -10%, rgba(102, 72, 214, 0.55), transparent 65%), radial-gradient(50% 40% at 90% 10%, rgba(25, 120, 190, 0.5), transparent 70%), linear-gradient(rgb(10, 20, 48), rgb(16, 42, 92) 55%, rgb(27, 79, 158)); }.tahoe::after { content: ""; position: absolute; inset: 0px; opacity: 0.18; mix-blend-mode: overlay; background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>"); }.wp-layer { position: absolute; inset: 0px; transition: opacity 0.8s; }.wp-layer.off { opacity: 0; }.wp-layer.reveal { animation: 1.6s cubic-bezier(0.6, 0, 0.2, 1) 0s 1 normal both running wp-reveal; }.wp-layer.fade { animation: 1.2s ease 0s 1 normal both running wp-fade; }@keyframes wp-reveal { 
  0% { clip-path: circle(0 at var(--x) var(--y)); }
  100% { clip-path: circle(150vmax at var(--x) var(--y)); }
}@keyframes wp-fade { 
  0% { opacity: 0; }
}.menubar { position: fixed; inset: 0px 0px auto; z-index: 8000; display: flex; align-items: center; justify-content: space-between; height: 30px; padding: 0px 10px 0px 12px; color: rgb(255, 255, 255); text-shadow: rgba(0, 0, 0, 0.35) 0px 1px 8px; background: linear-gradient(rgba(0, 0, 0, 0.18), rgba(0, 0, 0, 0)); }.menubar-left, .menubar-right { display: flex; align-items: center; height: 100%; }.menubar-right { gap: 16px; font-variant-numeric: tabular-nums; }.menubar-right svg { filter: drop-shadow(rgba(0, 0, 0, 0.3) 0px 1px 4px); }.mb-clock { white-space: pre; font-weight: 500; }.mb-anchor { position: relative; height: 100%; display: flex; align-items: center; }.mb-item { height: 24px; padding: 0px 9px; border-radius: 7px; font-size: 13px; font-weight: 500; }.mb-item.app { font-weight: 700; }.mb-item.apple { display: grid; place-items: center; padding: 0px 11px; }.mb-item.apple svg { filter: drop-shadow(rgba(0, 0, 0, 0.3) 0px 1px 4px); }.mb-item.open { background: rgba(255, 255, 255, 0.24); }.mb-menu { position: absolute; top: calc(100% + 1px); left: 0px; }.menubar-left > .mb-menu { top: 31px; }.menu { min-width: 232px; padding: 5px; border-radius: 13px; color: var(--label); text-shadow: none; background: rgba(36, 36, 40, 0.8); backdrop-filter: blur(40px) saturate(190%); box-shadow: rgba(255, 255, 255, 0.16) 0px 0px 0px 0.5px, rgba(255, 255, 255, 0.12) 0px 0.5px inset, rgba(0, 0, 0, 0.38) 0px 14px 44px; outline: none; animation: 0.12s ease-out 0s 1 normal none running menu-in; }@keyframes menu-in { 
  0% { opacity: 0; transform: translateY(-2px); }
}.menu-item { display: flex; align-items: center; width: 100%; height: 24px; padding: 0px 10px 0px 4px; border-radius: 7px; font-size: 13px; text-align: left; white-space: nowrap; }.menu-item.hot { background: var(--accent); color: rgb(255, 255, 255); }.menu-item:disabled { color: rgba(255, 255, 255, 0.28); }.menu-check { width: 18px; flex-shrink: 0; text-align: center; font-size: 12px; }.menu-label { flex: 1 1 0%; padding-right: 28px; }.menu-shortcut { display: flex; gap: 1px; font: inherit; color: rgba(255, 255, 255, 0.45); letter-spacing: 0.04em; }.menu-shortcut span { min-width: 12px; text-align: center; }.menu-item.hot .menu-shortcut { color: rgba(255, 255, 255, 0.85); }.menu-item:disabled .menu-shortcut { color: rgba(255, 255, 255, 0.2); }.menu-sep { height: 1px; margin: 5px 10px; border: 0px; background: rgba(255, 255, 255, 0.12); }.menu-heading { margin: 4px 10px 2px 22px; font-size: 11px; font-weight: 600; color: var(--secondary); }.menu-search { display: flex; align-items: center; gap: 6px; margin: 2px 2px 6px; padding: 0px 8px; height: 26px; border-radius: 7px; color: var(--secondary); background: rgba(255, 255, 255, 0.08); box-shadow: rgba(255, 255, 255, 0.14) 0px 0px 0px 0.5px inset; }.menu-search:focus-within { box-shadow: rgba(10, 132, 255, 0.5) 0px 0px 0px 3px; }.menu-search input { flex: 1 1 0%; min-width: 0px; border: 0px; background: none; color: rgb(255, 255, 255); font: inherit; outline: none; }.context-host { position: fixed; z-index: 9000; }.desk { position: absolute; inset: 0px; z-index: 1; }.hero7 { position: absolute; --hero-left: clamp(28px, 3.2vw, 56px); --hero-width: clamp(220px, 16vw, 300px); --window-left: calc(2 * var(--hero-left) + var(--hero-width) + max(0px, (100vw - 3 * var(--hero-left) - var(--hero-width) - 1400px) / 2)); left: var(--hero-left); top: 50%; width: var(--hero-width); transform: translateY(-50%); text-shadow: rgba(0, 0, 0, 0.32) 0px 2px 30px; }.hero7 > * { animation: rise 1s var(--ease-out) both; }.hero7 > :nth-child(2) { animation-delay: 0.08s; }.hero7 > :nth-child(3) { animation-delay: 0.16s; }.hero7 > :nth-child(4) { animation-delay: 0.24s; }@keyframes rise { 
